/**
 * ════════════════════════════════════════════════════════════════════
 *  SYNTHETIC BIOSIGNAL GENERATOR — DEVELOPMENT & TEST SUITE (PHASE 7)
 * ════════════════════════════════════════════════════════════════════
 * Generates realistic synthetic bio-signals for offline DSP pipeline
 * testing, validation, and development.
 * 
 * STRICT INVARIANT:
 * Every record generated by this module is explicitly labelled SIMULATED.
 * Never claim synthetic signals are real physiological measurements.
 */

import { BIO_SIGNAL_TYPES, PROVENANCE_TYPES } from './NeuroContextTypes.js';

export class SyntheticBiosignalGenerator {
  /**
   * Generates synthetic EEG data with controllable band powers and optional artifacts
   */
  generateEEG(durationSec = 2, Fs = 250, options = {}) {
    const N = Math.round(durationSec * Fs);
    const timestamps = [];
    const data = new Array(N);
    const startTime = options.startTime || Date.now();
    const alphaAmp = options.alphaAmp !== undefined ? options.alphaAmp : 25; // microvolts
    const betaAmp = options.betaAmp !== undefined ? options.betaAmp : 12;
    const thetaAmp = options.thetaAmp !== undefined ? options.thetaAmp : 8;
    const addBlinkArtifact = Boolean(options.addBlinkArtifact);

    for (let i = 0; i < N; i++) {
      const t = i / Fs;
      timestamps.push(startTime + Math.round(t * 1000));

      // Compose frequency components: 10Hz Alpha + 20Hz Beta + 6Hz Theta + Gaussian noise
      const alpha = alphaAmp * Math.sin(2 * Math.PI * 10 * t);
      const beta = betaAmp * Math.sin(2 * Math.PI * 20 * t);
      const theta = thetaAmp * Math.sin(2 * Math.PI * 6 * t);
      const noise = (Math.random() - 0.5) * 6;

      let sample = alpha + beta + theta + noise;

      // Inject high-amplitude eye-blink artifact around middle of epoch
      if (addBlinkArtifact && i > N * 0.4 && i < N * 0.6) {
        sample += 250 * Math.sin(Math.PI * (i - N * 0.4) / (N * 0.2));
      }

      data[i] = Math.round(sample * 100) / 100;
    }

    return {
      signalType: BIO_SIGNAL_TYPES.EEG,
      isSimulated: true,
      source: 'SIMULATED',
      provenance: PROVENANCE_TYPES.SYNTHETIC_SIMULATED,
      samplingRate: Fs,
      durationSec,
      timestamps,
      data,
      metadata: {
        syntheticFrequencyContent: ['10Hz Alpha', '20Hz Beta', '6Hz Theta'],
        hasBlinkArtifact: addBlinkArtifact
      }
    };
  }

  /**
   * Generates synthetic ECG with realistic QRS complexes at a specified BPM
   */
  generateECG(durationSec = 2, Fs = 500, bpm = 72, options = {}) {
    const N = Math.round(durationSec * Fs);
    const timestamps = [];
    const data = new Array(N).fill(0);
    const startTime = options.startTime || Date.now();
    const beatPeriodSamples = Math.round((60 / bpm) * Fs);

    for (let i = 0; i < N; i++) {
      timestamps.push(startTime + Math.round((i / Fs) * 1000));
    }

    // Place QRS spikes periodically
    for (let beat = Math.round(beatPeriodSamples * 0.2); beat < N; beat += beatPeriodSamples) {
      // P-wave (small positive deflection)
      const pIdx = beat - Math.round(0.16 * Fs);
      if (pIdx > 0 && pIdx < N) data[pIdx] += 120;

      // Q-wave (small dip)
      const qIdx = beat - Math.round(0.04 * Fs);
      if (qIdx > 0 && qIdx < N) data[qIdx] -= 200;

      // R-peak (large positive spike)
      if (beat > 0 && beat < N) data[beat] += 1800;

      // S-wave (sharp dip)
      const sIdx = beat + Math.round(0.04 * Fs);
      if (sIdx > 0 && sIdx < N) data[sIdx] -= 450;

      // T-wave (broader positive deflection)
      const tIdx = beat + Math.round(0.24 * Fs);
      if (tIdx > 0 && tIdx < N) data[tIdx] += 300;
    }

    // Add baseline wander and light noise
    for (let i = 0; i < N; i++) {
      const wander = 50 * Math.sin(2 * Math.PI * 0.3 * (i / Fs));
      const noise = (Math.random() - 0.5) * 30;
      data[i] = Math.round((data[i] + wander + noise) * 10) / 10;
    }

    return {
      signalType: BIO_SIGNAL_TYPES.ECG,
      isSimulated: true,
      source: 'SIMULATED',
      provenance: PROVENANCE_TYPES.SYNTHETIC_SIMULATED,
      samplingRate: Fs,
      durationSec,
      targetBpm: bpm,
      timestamps,
      data,
      metadata: {
        waveform: 'Synthetic QRS Complex',
        nominalBpm: bpm
      }
    };
  }

  /**
   * Generates synthetic PPG pulse waveform
   */
  generatePPG(durationSec = 2, Fs = 64, bpm = 72) {
    const N = Math.round(durationSec * Fs);
    const timestamps = [];
    const data = new Array(N);
    const startTime = Date.now();
    const beatPeriod = 60 / bpm;

    for (let i = 0; i < N; i++) {
      const t = i / Fs;
      timestamps.push(startTime + Math.round(t * 1000));
      const phase = (t % beatPeriod) / beatPeriod;

      // Asymmetric pulse with systolic peak and dicrotic notch
      let val = Math.exp(-Math.pow((phase - 0.2) / 0.08, 2)) * 1.0; // Systolic
      val += Math.exp(-Math.pow((phase - 0.45) / 0.12, 2)) * 0.4;  // Dicrotic
      val += (Math.random() - 0.5) * 0.05;

      data[i] = Math.round(val * 1000) / 1000;
    }

    return {
      signalType: BIO_SIGNAL_TYPES.PPG,
      isSimulated: true,
      source: 'SIMULATED',
      provenance: PROVENANCE_TYPES.SYNTHETIC_SIMULATED,
      samplingRate: Fs,
      durationSec,
      timestamps,
      data
    };
  }

  /**
   * Generates synthetic EDA (Skin Conductance) with slow tonic drift and phasic peaks
   */
  generateEDA(durationSec = 4, Fs = 32, options = {}) {
    const N = Math.round(durationSec * Fs);
    const timestamps = [];
    const data = new Array(N);
    const startTime = Date.now();
    const baseTonic = options.baseTonic || 5.2; // microSiemens
    const hasSCR = options.hasSCR !== undefined ? options.hasSCR : true;

    for (let i = 0; i < N; i++) {
      const t = i / Fs;
      timestamps.push(startTime + Math.round(t * 1000));
      let val = baseTonic + 0.1 * Math.sin(0.1 * t); // slow tonic baseline

      // Phasic response transient at t = 1.5s
      if (hasSCR && t > 1.5) {
        val += 0.4 * Math.exp(-(t - 1.5) / 1.2);
      }
      val += (Math.random() - 0.5) * 0.02;

      data[i] = Math.round(val * 1000) / 1000;
    }

    return {
      signalType: BIO_SIGNAL_TYPES.EDA,
      isSimulated: true,
      source: 'SIMULATED',
      provenance: PROVENANCE_TYPES.SYNTHETIC_SIMULATED,
      samplingRate: Fs,
      durationSec,
      timestamps,
      data
    };
  }

  /**
   * Generates synthetic 3-axis Accelerometer motion
   */
  generateMotion(durationSec = 2, Fs = 100, isMoving = false) {
    const N = Math.round(durationSec * Fs);
    const timestamps = [];
    const data = [];
    const startTime = Date.now();

    for (let i = 0; i < N; i++) {
      const t = i / Fs;
      timestamps.push(startTime + Math.round(t * 1000));
      if (isMoving) {
        // Active body shake: 2Hz sinusoidal movement + random acceleration
        data.push({
          x: Math.round((Math.sin(2 * Math.PI * 2 * t) * 1.8 + (Math.random() - 0.5) * 0.5) * 100) / 100,
          y: Math.round((Math.cos(2 * Math.PI * 2 * t) * 1.5 + (Math.random() - 0.5) * 0.5) * 100) / 100,
          z: Math.round((1.0 + Math.sin(2 * Math.PI * 4 * t) * 1.0) * 100) / 100
        });
      } else {
        // Stationary: 1G on Z axis (gravity), minimal noise
        data.push({
          x: Math.round((Math.random() - 0.5) * 0.04 * 100) / 100,
          y: Math.round((Math.random() - 0.5) * 0.04 * 100) / 100,
          z: Math.round((1.0 + (Math.random() - 0.5) * 0.04) * 100) / 100
        });
      }
    }

    return {
      signalType: BIO_SIGNAL_TYPES.MOTION,
      isSimulated: true,
      source: 'SIMULATED',
      provenance: PROVENANCE_TYPES.SYNTHETIC_SIMULATED,
      samplingRate: Fs,
      durationSec,
      timestamps,
      data
    };
  }
}

export const syntheticBiosignalGenerator = new SyntheticBiosignalGenerator();

